from taf.internal.scf.exceptions import ElementNotFound
from taf.gnb.oam.ne3s.ws.components.connection.messages import (
    NotificationMsg, NotificationGroup, NotificationType, AttachmentType)


class SWProvision(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(SWProvision, self).__init__(*args, **kwargs)
        self.managed_objects = self.attachment.get_managed_objects_for_class("SWProvision")

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(attachment, AttachmentType.Ocos)
                and attachment.get_managed_objects_for_class("SWProvision"))


class SWProvisionProgress(SWProvision):
    def __init__(self, *args, **kwargs):
        super(SWProvisionProgress, self).__init__(*args, **kwargs)

        mos = self.attachment.managed_objects
        self.status = mos[0].status.value
        self.textual_response = mos[0].textualResponse.value
        self.progress = mos[0].progress.value

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(attachment, AttachmentType.Ocos)
                and len(attachment.managed_objects) == 1
                and attachment.get_managed_objects_for_class("SWProvision")
                and attachment.has_elements(attachment.get_managed_objects_for_class("SWProvision")[0],
                                            ['progress', 'status', 'textualResponse']))


class SWProvisionError(SWProvision):
    def __init__(self, *args, **kwargs):
        SWProvision.__init__(self, *args, **kwargs)
        mo = self.managed_objects[0]
        self.status = mo.status.value
        self.textual_response = mo.textualResponse.value
        self.error_code = mo.errorCode.value

    @staticmethod
    def matches(soap, attachment):
        return (SWProvision.matches(soap, attachment)
                and len(attachment.managed_objects) == 1
                and attachment.has_elements(attachment.managed_objects[0],
                                            ['errorCode', 'status',
                                             'textualResponse']))


class NetworkSoftware(NotificationMsg):
    def __init__(self, *args, **kwargs):
        self.result = []
        super(NetworkSoftware, self).__init__(*args, **kwargs)

        mos = self.attachment.get_managed_objects_for_class("NetworkSoftware")
        for mo in mos:
            self.result.append((
                mo.versionID.value,
                mo.usageState.value,
                mo.technicalSpecificStatus.value,
                mo.mainFunction.value))

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(attachment, AttachmentType.Ocos)
                and attachment.get_managed_objects_for_class("NetworkSoftware"))


class VersionChange(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(VersionChange, self).__init__(*args, **kwargs)

        self.active_sw_release_ver = None
        self._set_active_version()

    def _set_active_version(self):
        for mo in self.attachment.managed_objects:
            for p in mo:
                try:
                    if p.name == 'activeSWReleaseVersion':
                        self.active_sw_release_ver = p.value.upper()
                        break
                except (AttributeError, ElementNotFound):
                    pass

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(attachment, AttachmentType.Ocos)
                and isinstance(soap, NotificationType.TransferNotification)
                and attachment.get_managed_objects_for_class('mnl'))


class SWMNotificationGroup(NotificationGroup):
    QUEUE_IDS = ("common_queue", )
    NOTIFICATIONS = (VersionChange, SWProvisionError, SWProvisionProgress,
                     SWProvision, NetworkSoftware)
